function testReviewNotice(job){return {id:'test-review:'+job.id,testReviewId:job.id,category:'exam',title:'テストの解答とコメントができました',body:'ノビーと解説を確認して、次の一問につなげよう。',at:job.completedAt};}
function testReviewReady(who){return !!currentUserId&&serverBootReady&&!authLeaseBlocked&&!isTrial()&&(!who||cloudSame(who));}
async function testReviewRequest(path,options,who){
    if(!testReviewReady(who))throw Object.assign(Error('session_changed'),{code:'session_changed'});
    const result=await textbookAIRequest(path,options,who);
    if(!testReviewReady(who))throw Object.assign(Error('session_changed'),{code:'session_changed'});
    return result;
}
window.nobiTestReviewAPI={
    available:()=>testReviewReady(),snapshot:()=>cloudIdentity(),matches:who=>testReviewReady(who),
    list:who=>testReviewRequest('/material-test-review',{},who),
    get:(id,who)=>testReviewRequest('/material-test-review?id='+encodeURIComponent(id),{},who),
    post:(body,who)=>testReviewRequest('/material-test-review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)},who),
    status:(id,who)=>testReviewRequest('/material-test-session?id='+encodeURIComponent(id),{},who),
    plan:who=>testReviewRequest('/plan',{},who),
    canNotify:()=>testReviewReady()&&noticeAllowed(testReviewNotice({id:'',completedAt:0})),
    notify:(job,who)=>{if(!testReviewReady(who)||document.hidden)return false;const before=noticeToastSerial;noticeToast(testReviewNotice(job));return noticeToastSerial>before;}
};
